Here's a Python program that meets your requirements. This program uses a list to store the items in the to-do list. The user can add, remove, and view items using the given commands.

```python
# Initialize an empty to-do list
to_do_list = []

def add_item(item):
    """Add an item to the to-do list."""
    to_do_list.append(item)
    print(f"To-do list: [{', '.join(to_do_list)}]")

def remove_item(item):
    """Remove an item from the to-do list."""
    if item in to_do_list:
        to_do_list.remove(item)
        print(f"Item '{item}' removed from the to-do list.")
    else:
        print(f"Item '{item}' not found in the to-do list.")

def view_to_do_list():
    """Display the current to-do list."""
    print("To-do list: [{},]".format(', '.join(to_do_list)))

def main():
    command = input("Enter a command (add, remove, view, or quit): ").lower()

    while command != "quit":
        if command == "add":
            item = input("Enter an item to add: ")
            add_item(item)

        elif command == "remove":
            item = input("Enter an item to remove: ")
            remove_item(item)

        elif command == "view":
            view_to_do_list()

        else:
            print("Invalid command. Please try again.")

        command = input("Enter a command (add, remove, view, or quit): ").lower()

if __name__ == "__main__":
    main()
```

This program will keep prompting the user for commands until they enter "quit". You can modify the `main()` function to allow the user to exit the program by pressing `Ctrl+C` (on Windows/Linux) or `Cmd+C` (on macOS).
